/美化名称/地雷系
二改二传随意，禁止商用


:root {
  --SmartThemeBodyColor: #000000;
  --SmartThemeQuoteColor: #C47A8A;      /* ✏️【引用色】改为粉色 */
  --SmartThemeEmColor: #B9679A;         /* ✏️【斜体色】改为深粉色 */
  --avatar-w: 118px;
  --avatar-h: 180px;
}

body {
  font-family: , sans-serif !important;
  font-weight: normal;
  background-color: #FFFFFF !important;
  color: var(--SmartThemeBodyColor) !important;
}

#top-settings-holder {
  background: #FFFFFF !important;
  border-bottom: 1px solid #F5C8D3 !important;  /* ✏️【顶栏边框】改为浅粉色 */
}

#chat { background: transparent !important; }

/* =========================================
   🚩 气泡设置：【开始】
   ========================================= */

/* 1. 基础布局容器 (mes) */
.mes {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;

  /* ✨ 固定355px宽度 */
  width: 355px !important;
  max-width: 355px !important;
  /* ✏️【整体上下位置】上边距从260px改为235px，把整个气泡往上提，和顶部图配合好 */
  margin: 280px auto 100px !important; 

  /* 背景三段式 - 中间平铺 */
  background: url("https://i.postimg.cc/t4pYJGCb/IMG_20260311_001350.png") repeat-y !important;
  background-size: 100% auto !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;

  /* 布局间距控制 */
  gap: 15px;
}

/* 2. 背景伪元素 (三段式切图：顶 & 底) */
.mes::before {
  content: "" !important;
  position: absolute !important;
  top: -247px !important;               /* ✏️【顶部位置】保持与顶部图片高度一致 */
  left: 0 !important;
  width: 100% !important;
  height: 247px !important;             /* ✏️【顶部高度】保持与图片原始高度一致 */
  background: url("https://i.postimg.cc/0yPbj12P/IMG_20260311_001335.png") no-repeat center bottom !important;
  /* 【关键修改】将 cover 改为 contain，确保图片完整显示不被拉伸 */
  background-size: contain !important;   /* ✏️【背景大小】contain=完整显示，cover=拉伸填满 */
  background-position: center bottom !important;
  z-index: -1 !important;
}

.mes::after {
  content: "" !important;
  position: absolute !important;
  bottom: -52px !important;
  left: 0 !important;
  width: 100% !important;
  height: 52px !important;
  background: url("https://i.postimg.cc/nhpCrfc8/IMG_20260311_001406.png") no-repeat center top !important;
  background-size: 100% 100% !important;
  z-index: -1 !important;
}


/* 3. 头像与三元素容器 */
.mes .mesAvatarWrapper {
  position: absolute !important;
  top: -230px !important; 
  left: 35% !important;
  transform: translateX(-50%) !important;
  z-index: 2 !important;

  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  background: none !important;
  padding: 0 !important;
}

/* 4. 文本块布局  */
.mes_block {
  display: flex !important;
  flex-direction: column !important;

  /* 核心修改：让文字块宽度超过100%并向右强制拉伸 */
  width: calc(100% + 10px) !important;  /* ✏️【宽度拉伸】数值越大越往右突 */
  margin-left: 0 !important;
  margin-right: -10px !important;       /* ✏️【右突力度】负值越大越往右突 */
margin-top: 1px !important;          /* ✏️【上移距离】负值越大越往上 */


  /* 内边距：控制文字距离背景边缘的真实距离 */
  padding: 0 20px 0 20px !important;      /* ✏️【文字边距】右20px控制文字离右边框距离 */

  box-sizing: border-box !important;
  z-index: 1 !important;
  overflow: visible !important;
}

/* 5. 文字排版细节优化 */
.mes_text {
  color: var(--SmartThemeBodyColor) !important;
  line-height: 1.8 !important;
  word-wrap: break-word !important;
  text-align: justify !important;       /* ✏️【对齐方式】justify=两端对齐 */
  padding-right: 15px !important;       /* ✏️【文字右边距】防止文字贴边 */
}

/* 对话块 (q) 美化 - 去掉特效，只保留颜色 */
.mes_text q, .mes_text blockquote {
  display: block;
  color: var(--SmartThemeQuoteColor) !important;
  /* 去掉边框和背景，只保留颜色 */
  border-left: none !important;
  background: none !important;
  padding: 0 !important;
  margin: 10px 0 !important;
  font-style: normal !important;
}

/* 动作/旁白 (em) 优化 */
.mes_text em, .mes_text i {
  color: var(--SmartThemeEmColor) !important;
  font-style: italic !important;
}

/* ===== 六、输入框提示文字自定义 ===== */

#nonQRFormItems {
    position: relative;
}

#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "ᜊ狂依存症候群ᜊ。" !important;
    color: #C47A8A !important;           /* ✏️【提示文字】改为亮粉色 */
    position: absolute;
    left: 58%;                 /* ✏️ 从50%改为58%，实现向右移动 */
    top: 50%;
    transform: translate(-50%, -50%);
    font-size: 10.5px;         /* ✏️ 字体大小 */
    letter-spacing: 1.2px;
    opacity: 0.55;
    font-style: italic;
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 60px);
}

/* =========================================
   🚩 头像样式定制：长方形 + 尖角 + 无边框
   ========================================= */

/* 头像容器 - 控制大小和形状（保持您设定的大小不变） */
.mes .avatar {
    width: 95px !important;    /* ✏️【宽度】保持95px不变 */
    height: 220px !important;   /* ✏️【高度】保持220px不变 */
    border-radius: 0 !important; /* 尖角 */

    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: none !important;
    background-color: transparent !important;
    background-image: none !important;

    /* 关键：确保头像容器本身不裁剪内容 */
    overflow: visible !important;
    position: relative !important;
    z-index: 1 !important;
}

/* 头像图片 */
.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;     /* 裁剪填充 */
    object-position: center !important; /* 居中 */

    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent !important;
    border-radius: 0 !important;
}

/* =========================================
   🚩 头像位置调整（保持您原来的设置）
   ========================================= */

.mes .mesAvatarWrapper {
    position: absolute !important;
    left: 76.9% !important;         /* ✏️【左右位置】保持您原来的设置 */
    top: -178px !important;          /* ✏️【上下位置】保持您原来的设置 */
    transform: translateX(-50%) !important;
    z-index: 2 !important;

    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    background: none !important;
    padding: 0 !important;

    /* 关键：确保头像的父容器也不裁剪内容 */
    overflow: visible !important;
}

/* =========================================
   🚩 头像框样式定制：作为独立贴图，完全覆盖在头像之上
   ========================================= */

/* 头像框不再受父容器大小限制，是一个完全独立的贴图 */
.mes .mesAvatarWrapper::after {
    content: "" !important;
    position: absolute !important;

    /* ✏️【定位】让头像框和头像位置重叠 */
    /* 这里的数值可能需要微调，以确保小贴纸位置正确 */
    top: -86px !important;      /* 负数=向上移动，正数=向下移动 */
    left: -40px !important;     /* 负数=向左移动，正数=向右移动 */

    /* ✏️【大小】直接设置头像框图片的原始大小 */
    width: 190px !important;     /* 宽度 */
    height: 320px !important;    /* 高度 */

    background-image: url("https://i.postimg.cc/8zNjcgPC/wu_biao_ti268_20260310233253.png") !important;
    background-size: contain !important;  /* 保持图片比例，不变形 */
    background-position: center !important;
    background-repeat: no-repeat !important;

    z-index: 999 !important;      /* 极高的层级，确保在最上面 */
    pointer-events: none !important;

    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    display: block !important;
}


/* ===== 去除顶栏底部阴影和边框（保持背景纯净）===== */
#top-settings-holder,
#top-bar,
.drawer,
.drawer-header,
.drawer-icon {
  box-shadow: none !important;
  -webkit-box-shadow: none !important;
  -moz-box-shadow: none !important;
  filter: none !important;
  -webkit-filter: none !important;
  border-bottom: none !important;
}



/* ===== 页面加载动画美化 ===== */

#preloader {
  position: fixed;
  margin: 0;
  padding: 0;
  top: 0;
  left: 0;
  z-index: 999999;
  width: 100vw;
  height: 100vh;
  background-color: #FFFFFF !important;  /* ✏️【背景颜色】白色 */
  opacity: 1;
}

#load-spinner {
  --spinner-size: 180px;                   /* ✏️【图标大小】数值越大图片越大 */
  transition: all var(--animation-duration-2x) ease-out;
  opacity: 1;
  top: calc(50% - var(--spinner-size) / 2);
  left: calc(50% - var(--spinner-size) / 2);
  position: absolute;
  width: var(--spinner-size);
  height: var(--spinner-size);
  background-image: url('https://i.postimg.cc/Hkzj7vV1/wu_biao_ti268_20260310232916.png') !important;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  animation: none !important;              /* 如需旋转动画，删除此行 */
}

#load-spinner::before {
  display: none !important;
}

/* ===== 底栏图标替换 ===== */

#send_form [class*="fa-"]::before {
    content: '' !important;
    display: inline-block;
    width: 22px;              /* ✏️【图标宽度】 */
    height: 22px;             /* ✏️【图标高度】 */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    vertical-align: middle;
}

#options_button::before {
    background-image: url('https://i.postimg.cc/nhpCrfcV/wu_biao_ti268_20260310233018.png') !important;
}

#extensionsMenuButton::before {
    background-image: url('https://i.postimg.cc/3xYdNQJx/wu_biao_ti268_20260310232959.png') !important;
}

#quick-reply-rocket-button i::before {
    background-image: url('https://i.postimg.cc/nhpCrfcV/wu_biao_ti268_20260310233018.png') !important;
}

#send_but::before {
    background-image: url('https://i.postimg.cc/3xYdNQJx/wu_biao_ti268_20260310232959.png') !important;
}

#mes_stop i::before {
    background-image: url('https://i.postimg.cc/sgsvxCDD/wu_biao_ti270_20260310234020.png') !important;
}





/* 悬停效果（可选） */
.mes_edit:hover, 
.extraMesButtonsHint:hover {
    transform: scale(1.1) !important;      /* 悬停时放大1.1倍 */
}

/* 确保按钮容器本身不影响图标显示 */
.mes_buttons {
    display: flex !important;
    align-items: center !important;
    gap: 4px !important;                   /* ✏️【按钮间距】可调整 */
}


/* --- 1. 扩展面板/设置区的按钮和标题 --- */
.inline-drawer-toggle,
.standoutHeader,
.extension_button,
#user-settings-block h4,
.inline-drawer-header {
    /* 移除默认的灰色渐变背景 */
    background-image: none !important;

    /* 背景颜色 - 纯白 */
    background-color: #FFFFFF !important;

    /* 边框 - 粉色系 */
    border: 1px solid #F5C8D3 !important;  /* ✏️【边框】浅粉色 */

    /* 文字颜色 - 深粉色 */
    color: #B9679A !important;              /* ✏️【文字颜色】深粉色 */

    /* 其他美化样式 */
    border-radius: 12px !important;
    box-shadow: 0 2px 5px rgba(255, 105, 180, 0.2) !important; /* ✏️【阴影】粉色阴影 */
}

/* 鼠标悬停时的样式 - 粉色加深 */
.inline-drawer-toggle:hover,
.extension_button:hover {
    border-color: #FF69B4 !important;       /* ✏️【悬停边框】亮粉色 */
    box-shadow: 0 0 8px rgba(255, 105, 180, 0.3) !important;
}


/* --- 2. 多选标签 (例如：世界书标签) --- */
.select2-container--default .select2-selection--multiple .select2-selection__choice {
    /* 移除默认的灰色渐变背景 */
    background-image: none !important;

    /* 背景颜色 - 纯白 */
    background-color: #FFFFFF !important;

    /* 边框 - 浅粉色 */
    border: 1px solid #F5C8D3 !important;   /* ✏️【标签边框】浅粉色 */

    /* 文字颜色 - 深粉色 */
    color: #F17DA5 !important;               /* ✏️【标签文字】深粉色 */

    /* 圆角 */
    border-radius: 8px !important;
}

/* 整个多选框的容器样式 */
.select2-container--default .select2-selection--multiple {
    background-image: none !important;
    background-color: #FFFFFF !important;
    border: 1px solid #F5C8D3 !important;   /* ✏️【容器边框】浅粉色 */
    border-radius: 12px !important;
}

/* 当多选框被激活(点击)时的样式 */
.select2-container--default.select2-container--open .select2-selection--multiple {
    border-color: #FF69B4 !important;        /* ✏️【激活边框】亮粉色 */
    box-shadow: 0 0 8px rgba(255, 105, 180, 0.3) !important;
}

/* ===== 全局白底设置 ===== */

/* 主背景设为白色 */
body {
    background-color: #FFFFFF !important;
}

/* 所有面板背景设为白色 */
.drawer-content,
#left-nav-panel,
#rm_api_block,
#AdvancedFormatting,
#WorldInfo,
#user-settings-block,
#rm_extensions_block,
#PersonaManagement,
#right-nav-panel {
    background-color: #FFFFFF !important;
    border-color: #FFE4E1 !important;  /* ✏️【面板边框】改为浅粉红 */
}

/* 输入框背景变白 */
select,
input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
textarea {
    background-color: #FFFFFF !important;
    border: 1px solid #F5C8D3 !important;  /* ✏️【输入框边框】浅粉色 */
    color: #000000 !important;
}

/* 下拉菜单选项背景 */
option {
    background-color: #FFFFFF !important;
    color: #000000 !important;
}

/* 按钮背景变浅 */
.menu_button,
.api_button {
    background-color: #FFF0F5 !important;  /* ✏️【按钮背景】改为 lavenderblush 浅粉 */
    border: 1px solid #F5C8D3 !important;   /* ✏️【按钮边框】浅粉色 */
    color: #F17DA5 !important;               /* ✏️【按钮文字】深粉色 */
}

/* 按钮悬停效果 */
.menu_button:hover,
.api_button:hover {
    background-color: #FFE4E1 !important;  /* ✏️【悬停背景】更深的浅粉 */
}

/* 消息区域背景 */
.mes {
    background-color: rgba(255, 255, 255, 0.9) !important;
}


/* 顶栏背景 */
#top-settings-holder {
    background-color: #FFFFFF !important;
    border-bottom: 1px solid #F5C8D3 !important;  /* ✏️【顶栏边框】浅粉色 */
}

/* 如果背景图导致透出黑色，可以临时注释掉背景图 */
/* #top-settings-holder {
    background-image: none !important;
} */

/* ===== 顶栏：图标可点击 + 底部背景图片 ===== */

/* 顶栏容器 - 背景图片 */
#top-settings-holder {
    background-image: url('https://i.postimg.cc/W1ThzcpB/wu_biao_ti273_20260311024157.png') !important;
    background-size: 100% 100% !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    border-bottom: none !important;
    min-height: 30px !important;
    position: relative !important;
}

/* 图标容器 - 负责点击 */
#top-settings-holder .drawer-icon {
    opacity: 1 !important;
    pointer-events: auto !important;
    position: relative !important;
    z-index: 5 !important;
    display: inline-block !important;
    width: 25px !important;                 /* ✏️【点击区域宽度】稍微调小 */
    height: 25px !important;                /* ✏️【点击区域高度】稍微调小 */
    background: transparent !important;
}

/* 图标图片 - 只负责显示，不负责点击 */
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    background-color: transparent !important;
    z-index: 4 !important;
    transition: transform 0.3s ease-in-out;
}

/* 悬停效果 - 作用于图片 */
#top-settings-holder .drawer-icon:hover::before {
    transform: scale(1.1);
}

/* ===== 图标图片分配===== */

/* 图标1: AI响应配置  */
#leftNavDrawerIcon::before {
    background-image: url('https://i.postimg.cc/nhpCrfcV/wu_biao_ti268_20260310233018.png') !important;
}

/* 图标2: API连接 */
#API-status-top::before {
    background-image: url('https://i.postimg.cc/3xYdNQJx/wu_biao_ti268_20260310232959.png') !important;
}

/* 图标3: AI回复格式化 */
.drawer-icon.fa-font::before {
    background-image: url('https://i.postimg.cc/nhpCrfcV/wu_biao_ti268_20260310233018.png') !important;
}

/* 图标4: 世界信息/世界书 */
#WIDrawerIcon::before {
    background-image: url('https://i.postimg.cc/3xYdNQJx/wu_biao_ti268_20260310232959.png') !important;
}

/* 图标5: 用户设置  */
.drawer-icon.fa-user-cog::before,
.drawer-icon.fa-user::before {
    background-image: url('https://i.postimg.cc/nhpCrfcV/wu_biao_ti268_20260310233018.png') !important;
}

/* 图标6: 背景图片  */
#backgrounds-drawer-toggle .drawer-icon::before {
    background-image: url('https://i.postimg.cc/3xYdNQJx/wu_biao_ti268_20260310232959.png') !important;
}

/* 图标7: 扩展 */
.drawer-icon.fa-cubes::before {
    background-image: url('https://i.postimg.cc/nhpCrfcV/wu_biao_ti268_20260310233018.png') !important;
}

/* 图标8: 用户角色管理  */
.drawer-icon.fa-face-smile::before {
    background-image: url('https://i.postimg.cc/nhpCrfcV/wu_biao_ti268_20260310233018.png') !important;
}

/* 图标9: 角色卡  */
#rightNavDrawerIcon::before {
    background-image: url('https://i.postimg.cc/3xYdNQJx/wu_biao_ti268_20260310232959.png') !important;
}

/* 图标10: 时光记忆 (右) - 新增扩展 */
