/* ===== 滑动条 - 粉嫩果冻版 ===== */

/* 1. 重置所有 <input type="range"> 的默认浏览器样式 */
input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    background: transparent !important;
    cursor: pointer;
}

/* 2. 设计滑块的“轨道” (Track) - 粉嫩渐变 */
input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 8px !important;                 /* ✏️【轨道粗细】可调整 */
    background: linear-gradient(to right, #FFB6C1, #FF9EB5) !important;  /* 粉嫩渐变 */
    border-radius: 20px !important;
    border: 1px solid rgba(255, 200, 220, 0.5) !important;
    box-shadow: inset 0 1px 3px rgba(255, 255, 255, 0.8) !important;
}

/* 3. 设计滑块的“手柄” (Thumb) - 使用自定义图标 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;    
    margin-top: -8px;                        /* ✏️【垂直居中】改了大小要调这里 */
    height: 35px !important;                  /* ✏️【图标高度】 */
    width: 35px !important;                   /* ✏️【图标宽度】 */

    /* 图标替换 */
    background-image: url('https://i.postimg.cc/htcfvRPR/IMG-20260311-041543.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;

    /* 移除默认样式 */
    background-color: transparent !important; 
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    transition: transform 0.2s ease !important;
}

/* 4. 鼠标悬停或拖动时放大 */
input[type="range"]:hover::-webkit-slider-thumb,
input[type="range"]:active::-webkit-slider-thumb {
    transform: scale(1.15) !important;
}

/* ===== Firefox 兼容 ===== */
input[type="range"]::-moz-range-track {
    height: 8px !important;
    background: linear-gradient(to right, #FFB6C1, #FF9EB5) !important;
    border-radius: 20px !important;
    border: 1px solid rgba(255, 200, 220, 0.5) !important;
}

input[type="range"]::-moz-range-thumb {
    height: 28px !important;
    width: 28px !important;
    background-image: url('https://i.postimg.cc/htcfvRPR/IMG-20260311-041543.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    transition: transform 0.2s ease !important;
}

input[type="range"]:hover::-moz-range-thumb,
input[type="range"]:active::-moz-range-thumb {
    transform: scale(1.15) !important;
}


